/**
 * Bulk issue import: the all-or-nothing batch write and the replay record that
 * lets the same key be uploaded again and get the first result back.
 *
 * Must call (do not reimplement): orgPredicate, toIssue, parseJsonArray, newId
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import type { Db } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { parseJsonArray, toIssue } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

/** Colour a label gets when an import creates it; it has no description. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export interface PreparedImportRow {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly labelNames: readonly string[];
  readonly dueAt: IsoTimestamp | null;
}

export interface ImportBatch {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importerId: UserId;
  readonly importKey: string;
  readonly rows: readonly PreparedImportRow[];
}

export interface ImportCommit {
  readonly replayed: boolean;
  readonly projectId: ProjectId;
  /** In file order. */
  readonly issues: readonly Issue[];
}

/** The earlier import recorded under `importKey`, or `null` if the key is unused. */
export function findImport(
  orgId: OrgId,
  importKey: string,
): ImportCommit | null {
  const db = getDb();
  const record = db
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!record) return null;

  return {
    replayed: true,
    projectId: record.projectId as ProjectId,
    issues: loadIssues(db, orgId, parseJsonArray<IssueId>(record.issueIds)),
  };
}

/**
 * Writes the whole batch in one transaction: missing labels, issue numbers
 * continuing after the project's highest, the issues with their labels, and
 * the replay record. A key that was committed in the meantime returns that
 * earlier import and writes nothing.
 */
export function commitImport(batch: ImportBatch): ImportCommit {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx): ImportCommit => {
    const earlier = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, batch.orgId),
          eq(issueImports.importKey, batch.importKey),
        ),
      )
      .get();
    if (earlier) {
      return {
        replayed: true,
        projectId: earlier.projectId as ProjectId,
        issues: loadIssues(
          tx,
          batch.orgId,
          parseJsonArray<IssueId>(earlier.issueIds),
        ),
      };
    }

    const labelIds = new Map<string, LabelId>(
      tx
        .select()
        .from(labels)
        .where(orgPredicate(labels.orgId, batch.orgId))
        .all()
        .map((label) => [label.name, label.id as LabelId]),
    );
    for (const name of new Set(batch.rows.flatMap((row) => row.labelNames))) {
      if (labelIds.has(name)) continue;
      const created = tx
        .insert(labels)
        .values({
          id: newId(),
          orgId: batch.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: labels.id })
        .get();
      labelIds.set(name, created.id as LabelId);
    }

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, batch.orgId),
          eq(issues.projectId, batch.projectId),
        ),
      )
      .get();
    const firstNumber = (highest?.value ?? 0) + 1;

    const created = batch.rows.map((row, index) => {
      const issue = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: batch.orgId,
          projectId: batch.projectId,
          number: firstNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: batch.importerId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const rowLabelIds = [...new Set(row.labelNames)].map((name) => {
        const labelId = labelIds.get(name);
        if (!labelId) throw new Error(`Label "${name}" was not resolved`);
        return labelId;
      });
      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({
              orgId: batch.orgId,
              issueId: issue.id,
              labelId,
            })),
          )
          .run();
      }

      return toIssue(issue, rowLabelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: batch.orgId,
        importKey: batch.importKey,
        projectId: batch.projectId,
        importedBy: batch.importerId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, projectId: batch.projectId, issues: created };
  });
}

/** Loads issues by id, keeping the order of `ids`. Archived issues are included. */
function loadIssues(
  db: Pick<Db, "select">,
  orgId: OrgId,
  ids: readonly IssueId[],
): readonly Issue[] {
  if (ids.length === 0) return [];

  const rows = db
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...ids])),
    )
    .all();

  const labelRows = db
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...ids]),
      ),
    )
    .all();

  const rowById = new Map(rows.map((row) => [row.id, row]));
  const labelsByIssue = new Map<string, LabelId[]>();
  for (const label of labelRows) {
    const bucket = labelsByIssue.get(label.issueId) ?? [];
    bucket.push(label.labelId as LabelId);
    labelsByIssue.set(label.issueId, bucket);
  }

  return ids.flatMap((id) => {
    const row = rowById.get(id);
    return row ? [toIssue(row, labelsByIssue.get(id) ?? [])] : [];
  });
}

