/**
 * Bulk import, gated in the same order as `createIssue`, then the whole batch
 * is checked — quota and rate allowance — before the single write. A key that
 * was imported before returns that earlier result and is not checked again, so
 * a project at its quota can still replay its own import. A successful batch
 * publishes one `issues.imported` event in place of the per-issue events.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  const earlier = issueImportRepo.findImport(input.orgId, input.importKey);
  if (earlier) {
    return { importKey: input.importKey, ...earlier };
  }

  assertNotArchived("Project", project.id, project);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  // Only live members can be assignees; anyone else leaves the row unassigned.
  const memberIds = await memberRepo.findActiveMemberIdsByEmail(input.orgId);
  const commit = issueImportRepo.commitImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importerId: actor.userId,
    importKey: input.importKey,
